	@Test
	void freshContendedReadReleasesPairedReservationBeforeGuardWait(@TempDir Path directory) throws Exception {
		try (Fixture fixture = Fixture.create(directory);
				GuardHolder holder = new GuardHolder(fixture.backing)) {
			ExecutorService executor = Executors.newSingleThreadExecutor();
			AtomicReference<Thread> reader = new AtomicReference<>();
			int permits = fixture.values.getTxnManager().availableOrdinaryPermits();
			long admissions = fixture.values.getTxnManager().ordinaryAdmissions();
			try {
				Future<?> scan = executor.submit(() -> {
					reader.set(Thread.currentThread());
					try (CloseableIteration<? extends Statement> rows = fixture.backing.new GuardedEstimatorStatementSource()
							.getStatements(null, null, null)) {
						assertEquals(1, count(rows));
					}
				});
				awaitGuardWait(reader);
				assertTrue(fixture.values.getTxnManager().ordinaryAdmissions() > admissions,
						"the failed guard attempt must actually admit a paired native view");
				assertEquals(permits, fixture.values.getTxnManager().availableOrdinaryPermits(),
						"the complete paired reservation must be released before the guard wait");
				holder.release();
				scan.get(5, TimeUnit.SECONDS);
			} finally {
				holder.release();
				executor.shutdownNow();
				assertTrue(executor.awaitTermination(5, TimeUnit.SECONDS));
			}
		}
	}

